-- ÜRETİLDİ: tool/gen_seed_sql.dart (kaynak: assets/seed/system.json). Elle düzenleme.

on conflict (key) do update set sort_order = excluded.sort_order, name_tr = excluded.name_tr, name_en = excluded.name_en, description_tr = excluded.description_tr, description_en = excluded.description_en, icon = excluded.icon, color = excluded.color;

on conflict (key) do update set sort_order = excluded.sort_order, name_tr = excluded.name_tr, name_en = excluded.name_en, hemisphere = excluded.hemisphere, mesh_name = excluded.mesh_name, is_inner = excluded.is_inner;

on conflict (root_category_key, region_key) do update set weight = excluded.weight, evidence_level = excluded.evidence_level, source_ids = excluded.source_ids, source_urls = excluded.source_urls, detail_tr = excluded.detail_tr, detail_en = excluded.detail_en;
